/**
 * Hive Capital Markets: the acknowledgment emailed to the person who submitted an intake.
 *
 * The form is public, so anyone can type someone else's address. This template is therefore fixed:
 * the only values that vary are the reference (generated by the server) and the form title (from HIVE_FORMS).
 * Nothing the visitor typed is included, so the form cannot be used to mail arbitrary text from bullnet.ai.
 *
 * The wording repeats the limits in the consent text (lib/hive-intake.ts). It promises no turnaround time
 * and does not use the word "case": until Sprint 2 the reference identifies an email, not a case record.
 */
import { HIVE_FORMS, type HiveForm } from './hive-intake.ts';

export interface AckEmail { subject: string; text: string; html: string }

const NEXT = 'A person reads every intake. We will contact you at this address about an initial assessment.';
const NOT_DONE = 'Nothing has been sent to a lender or any other third party, and no documents were collected. Please do not send documents by email.';
const LIMITS = 'BullNet is not a lender or a real estate broker. This is not an application for credit.';
const UNEXPECTED = 'If you did not submit this intake, reply to this email and we will remove it.';

export function ackEmail(form: HiveForm, ref: string): AckEmail {
  const kind = HIVE_FORMS[form].title;
  const lead = `Thank you. Your ${kind} intake reached BullNet.`;
  const text = [
    lead,
    '',
    `Reference: ${ref}`,
    'Keep it and quote it when you follow up.',
    '',
    `What happens next: ${NEXT}`,
    '',
    `What has not happened: ${NOT_DONE}`,
    '',
    LIMITS,
    UNEXPECTED,
    '',
    'Hive Capital Markets, BullNet',
    'The pencil is the point of truth.',
    'https://bullnet.ai/hive-capital-markets/',
  ].join('\n');

  // Brand lock: Obsidian #0B0F14, Platinum #E5E8EB, Signal Green #8ED13B. Text wordmark only: the B mark is not redrawn here.
  const p = 'margin:0 0 16px;font:15px/1.6 Arial,Helvetica,sans-serif;color:#0B0F14';
  const html = `<!doctype html>
<html lang="en"><body style="margin:0;padding:0;background:#E5E8EB">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#E5E8EB"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#FFFFFF">
<tr><td style="background:#0B0F14;padding:20px 28px;border-bottom:3px solid #8ED13B">
<div style="font:700 16px/1 Arial,Helvetica,sans-serif;letter-spacing:.18em;color:#FFFFFF">BULLNET</div>
<div style="margin-top:8px;font:11px/1 'Courier New',monospace;letter-spacing:.14em;color:#E5E8EB">HIVE CAPITAL MARKETS</div>
</td></tr>
<tr><td style="padding:28px">
<p style="${p}">${lead}</p>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 20px"><tr><td style="border-left:3px solid #8ED13B;background:#F4F5F6;padding:14px 16px">
<div style="font:11px/1 'Courier New',monospace;letter-spacing:.14em;color:#343438">REFERENCE</div>
<div style="margin-top:8px;font:700 18px/1.2 'Courier New',monospace;color:#0B0F14">${ref}</div>
<div style="margin-top:8px;font:13px/1.4 Arial,Helvetica,sans-serif;color:#343438">Keep it and quote it when you follow up.</div>
</td></tr></table>
<p style="${p}"><strong>What happens next.</strong> ${NEXT}</p>
<p style="${p}"><strong>What has not happened.</strong> ${NOT_DONE}</p>
<p style="margin:0;font:13px/1.6 Arial,Helvetica,sans-serif;color:#343438">${LIMITS} ${UNEXPECTED}</p>
</td></tr>
<tr><td style="padding:18px 28px;border-top:1px solid #E5E8EB;font:12px/1.6 Arial,Helvetica,sans-serif;color:#343438">
Hive Capital Markets, BullNet<br><em>The pencil is the point of truth.</em><br><a href="https://bullnet.ai/hive-capital-markets/" style="color:#0B0F14">bullnet.ai/hive-capital-markets</a>
</td></tr>
</table>
</td></tr></table>
</body></html>`;

  return { subject: `We received your intake: ${ref}`, text, html };
}
